import java.util.*;
import java.util.stream.Collectors;

public class Person {
    private final String name;
    private final int age;

    public Person(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public String getName() { return name; }
    public int getAge() { return age; }

    // Implemented using Java 8 streams
    public static List<String> adultNamesSorted(List<Person> people) {
        if (people == null) return Collections.emptyList();
        return people.stream()
            .filter(Objects::nonNull)
            .filter(p -> p.getAge() >= 18)
            .map(Person::getName)
            .filter(Objects::nonNull)
            .distinct()
            .sorted()
            .collect(Collectors.toList());
    }
}

public class Main {
    static class Person {
        String name;
        Person(String name) { this.name = name; }
    }

    public static void createAndRelease() {
        Person p = new Person("Alice");
        // remove the strong reference so the object becomes eligible for GC
        p = null;
    }

    public static void main(String[] args) {
        createAndRelease();
        // After createAndRelease returns, the Person is eligible for garbage collection
    }
}

Explanation: Creating a local Person reference and then assigning null removes the only strong reference, making the object eligible for GC when there are no other references.
